-- Phase A8 (carried hardening, the A6 security review's I1), generated by drizzle-kit from src/server/db/schema-site.ts and
-- reviewed: menu_items gains top_position — a top-level item's position again, NULL for a nested one — filled from
-- position for today's rows, then a unique index on (menu_key, top_position) and a check that keeps it equal to position.
-- A1's uq_menu_items_position (menu_key, parent_id, position) admits repeated NULL parents, so the database never held
-- top-level positions unique (the menu service did, by its root lock and its renumbering through a free range, which this
-- index accepts). MariaDB refuses a generated column over parent_id (its foreign key cascades), hence a written column.
-- Never edited after it has been applied.
ALTER TABLE `menu_items` ADD `top_position` int unsigned;--> statement-breakpoint
UPDATE `menu_items` SET `top_position` = `position` WHERE `parent_id` IS NULL;--> statement-breakpoint
ALTER TABLE `menu_items` ADD CONSTRAINT `uq_menu_items_top_position` UNIQUE(`menu_key`,`top_position`);--> statement-breakpoint
ALTER TABLE `menu_items` ADD CONSTRAINT `ck_menu_items_top` CHECK ((`menu_items`.`parent_id` IS NULL AND `menu_items`.`top_position` IS NOT NULL AND `menu_items`.`top_position` = `menu_items`.`position`) OR (`menu_items`.`parent_id` IS NOT NULL AND `menu_items`.`top_position` IS NULL));